package org.animallink.incident.infrastructure;
import io.minio.*;import io.minio.http.Method;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import java.util.*;
@Component public class MinioIncidentMediaFormalizer {
 private final MinioClient minio;private final String bucket;public MinioIncidentMediaFormalizer(MinioClient minio,@Value("${animallink.minio.bucket}")String bucket){this.minio=minio;this.bucket=bucket;}
 public List<Media> formalize(String userId,String parentId,String prefix,List<Input> inputs){List<Media> out=new ArrayList<>();for(Input in:inputs){if(!in.key().startsWith("incident-input/"+userId+"/"))throw new IllegalArgumentException("临时媒体不属于当前用户");if(!(in.contentType().startsWith("image/")||in.contentType().startsWith("video/")))throw new IllegalArgumentException("仅允许媒体类型");if(in.size()>10485760)throw new IllegalArgumentException("媒体大小超过限制");try{var stat=minio.statObject(StatObjectArgs.builder().bucket(bucket).object(in.key()).build());if(stat.size()!=in.size()||!stat.contentType().split(";")[0].equalsIgnoreCase(in.contentType()))throw new IllegalArgumentException("临时媒体元数据不匹配");String ext=in.contentType().startsWith("image/jpeg")?".jpg":in.contentType().startsWith("image/png")?".png":in.contentType().startsWith("image/webp")?".webp":in.contentType().startsWith("video/mp4")?".mp4":".bin";String target=prefix+"/"+parentId+"/"+String.format("%02d",in.sortOrder())+("case-actions".equals(prefix)?"-"+UUID.randomUUID():"")+ext;minio.copyObject(CopyObjectArgs.builder().bucket(bucket).object(target).source(CopySource.builder().bucket(bucket).object(in.key()).build()).build());out.add(new Media(UUID.randomUUID().toString(),target,in.contentType(),in.size(),in.sortOrder()));}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalStateException("MinIO 媒体正式化失败",e);}}return out;}
 public String presignedReadUrl(String objectKey){try{return minio.getPresignedObjectUrl(GetPresignedObjectUrlArgs.builder().method(Method.GET).bucket(bucket).object(objectKey).expiry(600).build());}catch(Exception e){throw new IllegalStateException("MinIO 媒体读取地址生成失败",e);}} public record Input(String key,String contentType,long size,int sortOrder){} public record Media(String id,String key,String contentType,long size,int sortOrder){}
}
